impl LadderLikeProperties {
    #[inline]
    #[must_use]
    pub fn from_index(mut index: u16) -> Self {
        Self {
            r#waterlogged: {
                let value = index % 2;
                index /= 2;
                value == 0
            },
            r#facing: {
                let value = index % HorizontalFacing::variant_count();
                index /= HorizontalFacing::variant_count();
                HorizontalFacing::from_index(value)
            },
        }
    }
    #[inline]
    #[must_use]
    pub fn from_state_id(id: BlockStateId) -> Self {
        let block = Block::from_state_id(id);
        let min_id = block.states[0].id.as_u16();
        Self::from_index(id.as_u16() - min_id)
    }
    #[inline]
    #[must_use]
    pub fn to_state_id(&self, block: &Block) -> BlockStateId {
        <Self as BlockProperties>::to_state_id(self, block)
    }
    #[inline]
    #[must_use]
    pub fn default(block: &Block) -> Self {
        <Self as BlockProperties>::default(block)
    }
}
impl BlockProperties for LadderLikeProperties {
    fn to_index(&self) -> u16 {
        let (index, _) = [
            (!self.r#waterlogged as u16, 2),
            (self.r#facing.to_index(), HorizontalFacing::variant_count()),
        ]
        .iter()
        .fold((0, 1), |(curr, mul), &(val, count)| {
            (curr + val * mul, mul * count)
        });
        index
    }
    #[allow(unused_assignments)]
    fn from_index(index: u16) -> Self {
        Self::from_index(index)
    }
    #[inline]
    #[allow(clippy::manual_range_patterns)]
    fn handles_block_id(block_id: BlockId) -> bool
    where
        Self: Sized,
    {
        matches!(
            block_id,
            BlockId::LADDER
                | BlockId::OAK_WALL_SIGN
                | BlockId::SPRUCE_WALL_SIGN
                | BlockId::BIRCH_WALL_SIGN
                | BlockId::ACACIA_WALL_SIGN
                | BlockId::CHERRY_WALL_SIGN
                | BlockId::JUNGLE_WALL_SIGN
                | BlockId::DARK_OAK_WALL_SIGN
                | BlockId::PALE_OAK_WALL_SIGN
                | BlockId::MANGROVE_WALL_SIGN
                | BlockId::POPLAR_WALL_SIGN
                | BlockId::BAMBOO_WALL_SIGN
                | BlockId::OAK_WALL_HANGING_SIGN
                | BlockId::SPRUCE_WALL_HANGING_SIGN
                | BlockId::BIRCH_WALL_HANGING_SIGN
                | BlockId::ACACIA_WALL_HANGING_SIGN
                | BlockId::CHERRY_WALL_HANGING_SIGN
                | BlockId::JUNGLE_WALL_HANGING_SIGN
                | BlockId::DARK_OAK_WALL_HANGING_SIGN
                | BlockId::PALE_OAK_WALL_HANGING_SIGN
                | BlockId::MANGROVE_WALL_HANGING_SIGN
                | BlockId::POPLAR_WALL_HANGING_SIGN
                | BlockId::CRIMSON_WALL_HANGING_SIGN
                | BlockId::WARPED_WALL_HANGING_SIGN
                | BlockId::BAMBOO_WALL_HANGING_SIGN
                | BlockId::ENDER_CHEST
                | BlockId::DEAD_TUBE_CORAL_WALL_FAN
                | BlockId::DEAD_BRAIN_CORAL_WALL_FAN
                | BlockId::DEAD_BUBBLE_CORAL_WALL_FAN
                | BlockId::DEAD_FIRE_CORAL_WALL_FAN
                | BlockId::DEAD_HORN_CORAL_WALL_FAN
                | BlockId::TUBE_CORAL_WALL_FAN
                | BlockId::BRAIN_CORAL_WALL_FAN
                | BlockId::BUBBLE_CORAL_WALL_FAN
                | BlockId::FIRE_CORAL_WALL_FAN
                | BlockId::HORN_CORAL_WALL_FAN
                | BlockId::CRIMSON_WALL_SIGN
                | BlockId::WARPED_WALL_SIGN
                | BlockId::BIG_DRIPLEAF_STEM
        ) || crate::dynamic_types::block_type(block_id).is_some_and(Self::handles_block_id)
    }
    fn to_state_id(&self, block: &Block) -> BlockStateId {
        if !Self::handles_block_id(block.id) {
            panic!(
                "{} is not a valid block for {}",
                block.name, "LadderLikeProperties"
            );
        }
        block.states[self.to_index() as usize].id
    }
    fn from_state_id(id: BlockStateId, block: &Block) -> Self {
        debug_assert!(
            Self::handles_block_id(block.id),
            "{} is not a valid block for {}",
            block.name,
            "LadderLikeProperties"
        );
        let min_id = block.states[0].id.as_u16();
        let max_id = block.states.last().map(|s| s.id.as_u16()).unwrap_or(min_id);
        if (min_id..=max_id).contains(&id.as_u16()) {
            Self::from_index(id.as_u16() - min_id)
        } else {
            #[cfg(debug_assertions)]
            panic!("State ID {} does not exist for {}", id, block.name);
            #[cfg(not(debug_assertions))]
            Self::from_index(0)
        }
    }
    fn default(block: &Block) -> Self {
        if !Self::handles_block_id(block.id) {
            panic!(
                "{} is not a valid block for {}",
                block.name, "LadderLikeProperties"
            );
        }
        Self::from_state_id(block.default_state.id)
    }
    fn to_props(&self) -> Vec<(&'static str, &'static str)> {
        vec![
            ("facing", self.r#facing.to_value()),
            (
                "waterlogged",
                if self.r#waterlogged { "true" } else { "false" },
            ),
        ]
    }
    #[allow(clippy::manual_range_patterns)]
    fn from_props(props: &[(&str, &str)], block: &Block) -> Self {
        #[cfg(debug_assertions)]
        if !Self::handles_block_id(block.id) {
            panic!(
                "{} is not a valid block for {}",
                block.name, "LadderLikeProperties"
            );
        }
        let mut block_props = Self::default(block);
        for (key, value) in props {
            match *key {
                "facing" => {
                    if let Some(parsed) = HorizontalFacing::from_value(value) {
                        block_props.r#facing = parsed;
                    }
                }
                "waterlogged" => match *value {
                    "true" => block_props.r#waterlogged = true,
                    "false" => block_props.r#waterlogged = false,
                    _ => {}
                },
                _ => {}
            }
        }
        block_props
    }
}
