impl ResinBrickWallLikeProperties {
    #[inline]
    #[must_use]
    pub fn from_index(mut index: u16) -> Self {
        Self {
            r#west: {
                let value = index % WestWall::variant_count();
                index /= WestWall::variant_count();
                WestWall::from_index(value)
            },
            r#waterlogged: {
                let value = index % 2;
                index /= 2;
                value == 0
            },
            r#up: {
                let value = index % 2;
                index /= 2;
                value == 0
            },
            r#south: {
                let value = index % SouthWall::variant_count();
                index /= SouthWall::variant_count();
                SouthWall::from_index(value)
            },
            r#north: {
                let value = index % NorthWall::variant_count();
                index /= NorthWall::variant_count();
                NorthWall::from_index(value)
            },
            r#east: {
                let value = index % EastWall::variant_count();
                index /= EastWall::variant_count();
                EastWall::from_index(value)
            },
        }
    }
    #[inline]
    #[must_use]
    pub fn from_state_id(id: BlockStateId) -> Self {
        let block = Block::from_state_id(id);
        let min_id = block.states[0].id.as_u16();
        Self::from_index(id.as_u16() - min_id)
    }
    #[inline]
    #[must_use]
    pub fn to_state_id(&self, block: &Block) -> BlockStateId {
        <Self as BlockProperties>::to_state_id(self, block)
    }
    #[inline]
    #[must_use]
    pub fn default(block: &Block) -> Self {
        <Self as BlockProperties>::default(block)
    }
}
impl BlockProperties for ResinBrickWallLikeProperties {
    fn to_index(&self) -> u16 {
        let (index, _) = [
            (self.r#west.to_index(), WestWall::variant_count()),
            (!self.r#waterlogged as u16, 2),
            (!self.r#up as u16, 2),
            (self.r#south.to_index(), SouthWall::variant_count()),
            (self.r#north.to_index(), NorthWall::variant_count()),
            (self.r#east.to_index(), EastWall::variant_count()),
        ]
        .iter()
        .fold((0, 1), |(curr, mul), &(val, count)| {
            (curr + val * mul, mul * count)
        });
        index
    }
    #[allow(unused_assignments)]
    fn from_index(index: u16) -> Self {
        Self::from_index(index)
    }
    #[inline]
    #[allow(clippy::manual_range_patterns)]
    fn handles_block_id(block_id: BlockId) -> bool
    where
        Self: Sized,
    {
        matches!(
            block_id,
            BlockId::RESIN_BRICK_WALL
                | BlockId::COBBLESTONE_WALL
                | BlockId::MOSSY_COBBLESTONE_WALL
                | BlockId::BRICK_WALL
                | BlockId::PRISMARINE_WALL
                | BlockId::RED_SANDSTONE_WALL
                | BlockId::MOSSY_STONE_BRICK_WALL
                | BlockId::GRANITE_WALL
                | BlockId::STONE_BRICK_WALL
                | BlockId::MUD_BRICK_WALL
                | BlockId::NETHER_BRICK_WALL
                | BlockId::ANDESITE_WALL
                | BlockId::RED_NETHER_BRICK_WALL
                | BlockId::SANDSTONE_WALL
                | BlockId::END_STONE_BRICK_WALL
                | BlockId::DIORITE_WALL
                | BlockId::BLACKSTONE_WALL
                | BlockId::POLISHED_BLACKSTONE_BRICK_WALL
                | BlockId::POLISHED_BLACKSTONE_WALL
                | BlockId::TUFF_WALL
                | BlockId::POLISHED_TUFF_WALL
                | BlockId::TUFF_BRICK_WALL
                | BlockId::SULFUR_WALL
                | BlockId::POLISHED_SULFUR_WALL
                | BlockId::SULFUR_BRICK_WALL
                | BlockId::CINNABAR_WALL
                | BlockId::POLISHED_CINNABAR_WALL
                | BlockId::CINNABAR_BRICK_WALL
                | BlockId::COBBLED_DEEPSLATE_WALL
                | BlockId::POLISHED_DEEPSLATE_WALL
                | BlockId::DEEPSLATE_TILE_WALL
                | BlockId::DEEPSLATE_BRICK_WALL
        ) || crate::dynamic_types::block_type(block_id).is_some_and(Self::handles_block_id)
    }
    fn to_state_id(&self, block: &Block) -> BlockStateId {
        if !Self::handles_block_id(block.id) {
            panic!(
                "{} is not a valid block for {}",
                block.name, "ResinBrickWallLikeProperties"
            );
        }
        block.states[self.to_index() as usize].id
    }
    fn from_state_id(id: BlockStateId, block: &Block) -> Self {
        debug_assert!(
            Self::handles_block_id(block.id),
            "{} is not a valid block for {}",
            block.name,
            "ResinBrickWallLikeProperties"
        );
        let min_id = block.states[0].id.as_u16();
        let max_id = block.states.last().map(|s| s.id.as_u16()).unwrap_or(min_id);
        if (min_id..=max_id).contains(&id.as_u16()) {
            Self::from_index(id.as_u16() - min_id)
        } else {
            #[cfg(debug_assertions)]
            panic!("State ID {} does not exist for {}", id, block.name);
            #[cfg(not(debug_assertions))]
            Self::from_index(0)
        }
    }
    fn default(block: &Block) -> Self {
        if !Self::handles_block_id(block.id) {
            panic!(
                "{} is not a valid block for {}",
                block.name, "ResinBrickWallLikeProperties"
            );
        }
        Self::from_state_id(block.default_state.id)
    }
    fn to_props(&self) -> Vec<(&'static str, &'static str)> {
        vec![
            ("east", self.r#east.to_value()),
            ("north", self.r#north.to_value()),
            ("south", self.r#south.to_value()),
            ("up", if self.r#up { "true" } else { "false" }),
            (
                "waterlogged",
                if self.r#waterlogged { "true" } else { "false" },
            ),
            ("west", self.r#west.to_value()),
        ]
    }
    #[allow(clippy::manual_range_patterns)]
    fn from_props(props: &[(&str, &str)], block: &Block) -> Self {
        #[cfg(debug_assertions)]
        if !Self::handles_block_id(block.id) {
            panic!(
                "{} is not a valid block for {}",
                block.name, "ResinBrickWallLikeProperties"
            );
        }
        let mut block_props = Self::default(block);
        for (key, value) in props {
            match *key {
                "east" => {
                    if let Some(parsed) = EastWall::from_value(value) {
                        block_props.r#east = parsed;
                    }
                }
                "north" => {
                    if let Some(parsed) = NorthWall::from_value(value) {
                        block_props.r#north = parsed;
                    }
                }
                "south" => {
                    if let Some(parsed) = SouthWall::from_value(value) {
                        block_props.r#south = parsed;
                    }
                }
                "up" => match *value {
                    "true" => block_props.r#up = true,
                    "false" => block_props.r#up = false,
                    _ => {}
                },
                "waterlogged" => match *value {
                    "true" => block_props.r#waterlogged = true,
                    "false" => block_props.r#waterlogged = false,
                    _ => {}
                },
                "west" => {
                    if let Some(parsed) = WestWall::from_value(value) {
                        block_props.r#west = parsed;
                    }
                }
                _ => {}
            }
        }
        block_props
    }
}
